<?php
require_once __DIR__ . '/../includes/layout.php';

// Teachers save attendance; other roles view it.
$me=require_login(); $pdo=db(); $error='';
if ($me['role']==='teacher' && $_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $classId=(int)($_POST['class_id']??0); $date=$_POST['attendance_date']??date('Y-m-d'); $owned=$pdo->prepare('SELECT id FROM classes WHERE id=? AND teacher_id=?');$owned->execute([$classId,$me['id']]); if(!$owned->fetch())$error='You can only manage your own classes.';elseif(($_POST['action']??'')==='delete'){$pdo->prepare('DELETE FROM attendance WHERE id=?')->execute([(int)$_POST['id']]);redirect('attendance.php?class_id='.$classId.'&date='.$date,'Attendance record deleted.');}else{foreach(($_POST['status']??[]) as $studentId=>$status){if(!in_array($status,['present','absent','late','excused'],true))continue;$pdo->prepare('INSERT INTO attendance(class_id,student_id,attendance_date,status,recorded_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),recorded_by=VALUES(recorded_by)')->execute([$classId,(int)$studentId,$date,$status,$me['id']]);}redirect('attendance.php?class_id='.$classId.'&date='.$date,'Attendance saved.');}}
if($me['role']==='teacher'){$q=$pdo->prepare('SELECT id,class_code,class_name FROM classes WHERE teacher_id=? ORDER BY class_code');$q->execute([$me['id']]);$classes=$q->fetchAll();$classId=(int)($_GET['class_id']??($classes[0]['id']??0));$date=$_GET['date']??date('Y-m-d');$q=$pdo->prepare('SELECT u.id,u.full_name,COALESCE(a.status,\'present\') status,a.id attendance_id FROM enrollments e JOIN users u ON u.id=e.student_id LEFT JOIN attendance a ON a.class_id=e.class_id AND a.student_id=u.id AND a.attendance_date=? WHERE e.class_id=? ORDER BY u.full_name');$q->execute([$date,$classId]);$records=$q->fetchAll();page_start('Record Attendance',$me);?><section class="panel"><div class="panel-heading"><div><h2>Attendance register</h2><p>Select a class and date, then save each student status.</p></div></div><form method="get" class="filter-row"><select name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId===$c['id']?'selected':''?>><?=e($c['class_code'].' — '.$c['class_name'])?></option><?php endforeach;?></select><input name="date" type="date" value="<?=e($date)?>"><button class="btn btn-secondary">Load</button></form><?php if(!$classes):?><p class="muted">You have no assigned classes.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="class_id" value="<?=$classId?>"><input type="hidden" name="attendance_date" value="<?=e($date)?>"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Status</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=e($r['full_name'])?></td><td><select name="status[<?=$r['id']?>]"><?php foreach(['present','absent','late','excused'] as $s):?><option value="<?=$s?>" <?=$r['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></td></tr><?php endforeach;?></tbody></table></div><br><button class="btn btn-primary">Save Attendance</button></form><?php endif;?></section><?php page_end();
} else { $params=[];$sql='SELECT a.*,u.full_name student_name,c.class_code,c.class_name,teacher.full_name teacher_name FROM attendance a JOIN users u ON u.id=a.student_id JOIN classes c ON c.id=a.class_id JOIN users teacher ON teacher.id=c.teacher_id';if($me['role']==='student'){$sql.=' WHERE a.student_id=?';$params[]=$me['id'];}$sql.=' ORDER BY a.attendance_date DESC,u.full_name';$q=$pdo->prepare($sql);$q->execute($params);$records=$q->fetchAll();page_start($me['role']==='student'?'My Attendance':'Attendance Records',$me);?><section class="panel"><div class="panel-heading"><div><h2>Attendance history</h2><p><?=count($records)?> record(s)</p></div></div><div class="table-wrap"><table><thead><tr><?php if($me['role']==='admin'):?><th>Student</th><?php endif;?><th>Class</th><th>Date</th><th>Status</th><th>Teacher</th></tr></thead><tbody><?php foreach($records as $r):?><tr><?php if($me['role']==='admin'):?><td><?=e($r['student_name'])?></td><?php endif;?><td><?=e($r['class_code'])?></td><td><?=e($r['attendance_date'])?></td><td><?=e(ucfirst($r['status']))?></td><td><?=e($r['teacher_name'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php page_end(); }
